CREATE TABLE flashcards (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, material_id BIGINT NULL, front TEXT NOT NULL, back TEXT NOT NULL, source_reference VARCHAR(120) NULL, last_reviewed DATE NULL, next_review DATE NULL, interval_days INT NOT NULL DEFAULT 0, ease_factor DOUBLE NOT NULL DEFAULT 2.5, review_count INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_flashcard_owner FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_flashcard_material FOREIGN KEY(material_id) REFERENCES materials(id) ON DELETE SET NULL, INDEX idx_flashcard_due(owner_id,next_review));
